-- university-network (SPEC.md): every public ΑΕΙ in Greece, Cyprus public + private universities, Greek colleges.
-- Generated by supabase/data/institutions.py (edit there, then regenerate). Sources: el.wikipedia «Ανώτατα
-- Εκπαιδευτικά Ιδρύματα στην Ελλάδα» + each university's article / site for departments; email domains checked
-- against their MX records. Institutions without a department list verify without one ("Δεν βρίσκω το τμήμα μου").
-- Idempotent: ON CONFLICT updates names / domains / departments, never deletes.

ON CONFLICT (id) DO UPDATE SET name_el = excluded.name_el, name_en = excluded.name_en, short_el = excluded.short_el,
  short_en = excluded.short_en, email_domains = excluded.email_domains, city = excluded.city;

ON CONFLICT (id) DO UPDATE SET name_el = excluded.name_el, name_en = excluded.name_en, short_el = excluded.short_el,
  short_en = excluded.short_en, years = excluded.years, position = excluded.position;
